import{z as C,x as o,o as A,c as n,q as s,j as r,D as e,d as B,s as l,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"无线上的 TCP","description":"","frontmatter":{"title":"无线上的 TCP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcp-wireless.md","filePath":"cs/tcp-wireless.md","lastUpdated":1791063341000}'),p={name:"cs/tcp-wireless.md"};function P(d,E,F,T,D,c){const t=o("Mermaid");return A(),n("div",null,[E[2]||(E[2]=s('<h1 id="无线上的-tcp" tabindex="-1">无线上的 TCP <a class="header-anchor" href="#无线上的-tcp" aria-label="Permalink to &quot;无线上的 TCP&quot;">​</a></h1><div class="epigraph"><p>空口误码与切换造成的丢包不是管道满；TCP 若当拥塞减窗，就把完好的 $C$ 浪费掉。</p><footer>—— 据 RFC 3481 2.5G/3G 上的 TCP；Balakrishnan et al. 无线 TCP 综述整理</footer></div><p><a href="/cs/satellite-latency">卫星</a> 已给误码≠拥塞。<a href="/cs/wifi-frames-ofdm">802.11 ACK</a> 做链路重传。<a href="/cs/delay-based-cc">上一课</a> 的延迟信号也会被调度抖动污染。缺口是<strong>蜂窝/Wi‑Fi 上的 TCP 行为</strong>：ELN、PEPs、链路 ARQ 与 RTO。本课结束新传输课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无线丢：衰落、碰撞、切换。链路 ARQ 已努力，仍可能超时。TCP 看到洞就 MD 或 RTO。对策分层：更好的链路 FEC/ARQ（PHY 课）、显式失错通知（少见）、冻结窗口在切换时、PEP 拆连接（破坏端到端）、BBR/延迟 CC 少抽空、QUIC 快速探测。5G URLLC 走专切片，不靠修 TCP。</p><p>不要把「无线 TCP」写成换一个 cc 算法名就结束。</p><p><span class="marginnote">RFC 3481。中间 PEP 有争议（Saltzer）。本课列机制，不推销拆连接。</span></p><p><span class="marginnote">术语翻译：PEP（性能增强代理）是&quot;把一条 TCP 连接拆成两段&quot;的中间盒——无线那段由它本地应答、本地重传，性能上去了，但端到端的承诺被拆掉了，这正是它有争议的原因。</span></p><h3 id="空口丢-管道满" tabindex="-1">空口丢≠管道满 <a class="header-anchor" href="#空口丢-管道满" aria-label="Permalink to &quot;空口丢≠管道满&quot;">​</a></h3><p>链路 ARQ 会掩盖或推迟。假 MD 浪费 \\(C\\)。PEP 破端到端。先问链路再改 CC。URLLC 走切片不靠修 TCP。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：拥塞丢 vs 无线丢。画：空口丢 → 假 MD → 吞吐低于 \\(C\\)。与 MPTCP：坏口切子流。与 RoCE：无线一般不跑无损 RDMA。</p>',12)),(A(),r(i,null,{default:e(()=>[l(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20WIRE%5B%22%E6%97%A0%E7%BA%BF%E8%AF%AF%E7%A0%81%22%5D%20--%3E%20HOLE%5B%22TCP%20%E8%A7%81%E6%B4%9E%22%5D%0A%20%20HOLE%20--%3E%20MD%5B%22%E8%AF%AF%E5%BD%93%E6%8B%A5%E5%A1%9E%22%5D%0A%20%20ARQ%5B%22%E9%93%BE%E8%B7%AF%E9%87%8D%E4%BC%A0%22%5D%20--%3E%20MASK%5B%22%E6%8E%A9%E7%9B%96%E6%88%96%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20MASK%20--%3E%20RTO%5B%22%E4%BB%8D%E5%8F%AF%E8%83%BD%E8%B6%85%E6%97%B6%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"缓冲膨胀在 LTE 基站很重，交互差。AQM 在基站有帮助。窗口缩放仍要，BDP 随无线 \\(C\\) 变。MSS 小一点抗误码重传代价，与容量摊销权衡。抓包看到的 RTT 含调度，不是传播。",-1)),E[5]||(E[5]=a("p",null,"端到端：应用 FEC（实时后课）比 PEP 更符合 Saltzer。",-1)),E[6]||(E[6]=a("p",null,"无线链路上发现丢包时，各层对策其实是一条决策路径——先问链路，再动 CC：",-1)),(A(),r(i,null,{default:e(()=>[l(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E8%A7%82%E6%B5%8B%E5%88%B0%E4%B8%A2%E5%8C%85%E6%88%96%E5%BB%B6%E8%BF%9F%E4%B8%8A%E5%8D%87%22%7D%20--%3E%20LINK%7B%22%E8%83%BD%E7%A1%AE%E8%AE%A4%E6%98%AF%E7%A9%BA%E5%8F%A3%E8%AF%AF%E7%A0%81%E6%88%96%E5%88%87%E6%8D%A2%3F%22%7D%0A%20%20LINK%20--%3E%7C%22%E6%98%AF%22%7C%20FIX%5B%22%E4%BA%A4%E7%BB%99%20FEC%20%E4%B8%8E%E9%93%BE%E8%B7%AF%20ARQ%2C%20TCP%20%E5%B0%BD%E9%87%8F%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20LINK%20--%3E%7C%22%E5%90%A6%22%7C%20CC%5B%22%E6%8C%89%E6%8B%A5%E5%A1%9E%E4%BF%A1%E5%8F%B7%E5%87%8F%E5%B0%8F%E7%AA%97%E5%8F%A3%22%5D%0A%20%20FIX%20--%3E%20SW%7B%22%E5%8F%91%E7%94%9F%E5%9C%A8%E5%88%87%E6%8D%A2%E7%9E%AC%E9%97%B4%3F%22%7D%0A%20%20SW%20--%3E%7C%22%E6%98%AF%22%7C%20FRZ%5B%22%E5%86%BB%E7%BB%93%E7%AA%97%E5%8F%A3%E4%B8%8E%E8%AE%A1%E6%97%B6%E5%99%A8%2C%20%E6%81%A2%E5%A4%8D%E5%90%8E%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20SW%20--%3E%7C%22%E5%90%A6%22%7C%20QU%5B%22%E6%94%B9%E7%94%A8%20QUIC%20%E7%9A%84%E5%BF%AB%E9%80%9F%E6%8E%A2%E6%B5%8B%22%5D%0A%20%20CC%20--%3E%20PEPQ%7B%22%E5%8F%AF%E6%8E%A5%E5%8F%97%E6%8B%86%E8%BF%9E%E6%8E%A5%3F%22%7D%0A%20%20PEPQ%20--%3E%7C%22%E5%90%A6%22%7C%20E2E%5B%22%E7%AB%AF%E5%88%B0%E7%AB%AF%3A%20%E5%BA%94%E7%94%A8%E5%B1%82%20FEC%20%E6%88%96%E5%BB%B6%E8%BF%9F%E5%9E%8B%20CC%22%5D%0A%20%20PEPQ%20--%3E%7C%22%E6%98%AF%22%7C%20PEPR%5B%22%E4%B8%8A%20PEP%20%E4%BB%A3%E7%90%86%2C%20%E7%89%BA%E7%89%B2%E7%AB%AF%E5%88%B0%E7%AB%AF%E8%AF%AD%E4%B9%89%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=s('<p><span class="marginnote">数字实例：误码率不变时，MSS 越大单个段撞上坏字节的概率越高——1500 字节的段错了要整段重传，MSS 减半后单次重传代价大约减半，但头部开销占比翻倍，是权衡不是免费午餐。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Snoop TCP 的全部代理状态。HTTP/1.1 持久连接是下一单元第一课。后课默认：无线丢包要先问链路，再问 CC。</p><p>把 RTO 下限盲目降到微秒会在公网误触发。</p><p><span class="marginnote">常见误区：容易以为&quot;无线上网慢&quot;就该换更激进的拥塞算法。若丢包源自空口误码或切换，再激进的算法也在做错题——正确的顺序是先确认链路，再谈 CC。</span></p><p>下一课<a href="/cs/http11-persistent-chunked">HTTP/1.1 持久连接与分块</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无线丢失≠瓶颈满。</li><li>链路 ARQ、谨慎 CC、多径是配套。</li><li>PEP 换性能、破端到端。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 3481；无线 TCP 文献。</li></ul>',8))])}const u=C(p,[["render",P]]);export{m as __pageData,u as default};
